/**
 * Generates the icon picker's sprite sheet, its search metadata, and the name
 * set the shared entity-icon defaults validate against.
 *
 * The picker does not import 1,054 React components. It imports one SVG
 * `<symbol>` per icon in a single sprite, plus the name/category/tags records
 * the search filters over. Both are generated from `@tabler/icons` and
 * committed, for the same reason `packages/feedback-widget` commits its
 * sprite: `pnpm check` has to work without running a code generator, and a
 * regenerated file should show up as a reviewable diff when the icon set moves.
 * The name set lives in `@feeblo/web-shared` beside the resolver that reads it;
 * it is only the names, not the labels and tags, so the search metadata stays
 * code-split.
 *
 * Run it after bumping `@tabler/icons` in the catalog:
 *
 *   pnpm --filter @feeblo/ui icons:generate
 *
 * The output is generated; edit this script, not the generated files.
 */
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { optimize } from "svgo";

type TablerStyle = {
  version: string;
  unicode: string;
};

type TablerIcon = {
  name: string;
  category: string;
  // The catalogue mixes words and numbers: `circle-number-0` tags itself `0`,
  // and `bong` tags itself `420`.
  tags: Array<string | number>;
  styles: Record<string, TablerStyle>;
};

type IconRecord = {
  name: string;
  label: string;
  category: number;
  tags: string[];
};

/**
 * The sprite and `sprite.ts` have to agree on the id, or every icon renders
 * blank with nothing failing. The generated module exports it so the reader
 * uses the value the writer wrote.
 */
const SYMBOL_ID_PREFIX = "tabler-filled-";

// Hoisted out of the per-icon loop: a literal inside `generateIcon` would
// allocate 1,054 copies of each expression.
const BACKGROUND_PATH_PATTERN =
  /<path stroke="none" d="M0 0h24v24H0z" fill="none"\s*\/>/;

const SVG_OPEN_PATTERN = /^<svg[^>]*>/;

const SVG_CLOSE_PATTERN = /<\/svg>\s*$/;

/**
 * Each icon is one `readFile`. Reading all 1,054 at once is fine on a CI runner
 * and can exhaust the descriptor limit on a developer machine, so the batch is
 * bounded. `Array.fromAsync` awaits each batch before starting the next, which
 * keeps the order (and therefore the generated files) deterministic.
 */
const READ_CONCURRENCY = 32;

const require = createRequire(import.meta.url);

const tablerRoot = dirname(require.resolve("@tabler/icons/package.json"));

const outputDirectory = fileURLToPath(
  new URL("../src/icon-picker/generated", import.meta.url)
);

/**
 * The name-only module the entity icon defaults import.
 *
 * `@feeblo/web-shared` owns the resolver and cannot import from
 * `@feeblo/ui` (the UI package depends on it), so the generator writes this
 * one file into web-shared. It carries no labels or tags; those stay in the
 * lazy catalogue.
 */
const nameSetOutputDirectory = fileURLToPath(
  new URL("../../web-shared/src/icons/generated", import.meta.url)
);

// SAFETY: `@tabler/icons` publishes `package.json` and `icons.json` with these
// shapes; a mismatch would be a wrong dependency and not a runtime condition.
const tablerPackage = JSON.parse(
  await readFile(join(tablerRoot, "package.json"), "utf8")
) as { version: string };

// SAFETY: the same package's manifest; the filter below only reads fields the
// catalogue has held for every release that ships a `filled` style.
const catalogue = JSON.parse(
  await readFile(join(tablerRoot, "icons.json"), "utf8")
) as Record<string, TablerIcon>;

const tablerVersion = tablerPackage.version;

const filledIcons = Object.values(catalogue).filter((icon) =>
  Object.hasOwn(icon.styles, "filled")
);

const categoryNames = [
  ...new Set(filledIcons.map((icon) => icon.category)),
].toSorted();

const categoryIndexByName = new Map(
  categoryNames.map((name, index) => [name, index])
);

const sortedIcons = filledIcons.toSorted((a, b) =>
  compareNames(a.name, b.name)
);

type GeneratedIcon = {
  record: IconRecord;
  symbol: string;
};

const generatedBatches = await Array.fromAsync(
  { length: Math.ceil(sortedIcons.length / READ_CONCURRENCY) },
  (_, batchIndex) => {
    const batch = sortedIcons.slice(
      batchIndex * READ_CONCURRENCY,
      (batchIndex + 1) * READ_CONCURRENCY
    );

    return Promise.all(
      batch.map((icon) => {
        const category = categoryIndexByName.get(icon.category);

        if (category === undefined) {
          throw new Error(`No category index for ${icon.name}`);
        }

        return generateIcon(icon, category);
      })
    );
  }
);

const generatedIcons = generatedBatches.flat();

const sprite = [
  `<!-- Generated by packages/ui/scripts/generate-tabler-filled-sprite.ts. Do not edit.`,
  `     Tabler Icons ${tablerVersion} (MIT): https://tabler.io/icons -->`,
  `<svg xmlns="http://www.w3.org/2000/svg">`,
  ...generatedIcons.map((icon) => icon.symbol),
  `</svg>`,
  ``,
].join("\n");

const symbolPrefix = [
  `// Generated by packages/ui/scripts/generate-tabler-filled-sprite.ts. Do not edit.`,
  `// Kept separate from \`tabler-filled-icons.ts\` so a statically imported`,
  `// constant does not pull the lazy catalogue chunk into the initial bundle.`,
  `export const TABLER_FILLED_SYMBOL_PREFIX = ${JSON.stringify(SYMBOL_ID_PREFIX)};`,
  ``,
].join("\n");

const iconNames = [
  `// Generated by packages/ui/scripts/generate-tabler-filled-sprite.ts. Do not edit.`,
  `// Source: @tabler/icons ${tablerVersion} (MIT). See LICENSE-tabler-icons.txt.`,
  `export const TABLER_FILLED_ICON_NAMES: ReadonlySet<string> = new Set([`,
  ...generatedIcons.map(({ record }) => `  ${JSON.stringify(record.name)},`),
  `]);`,
  ``,
].join("\n");

const metadata = [
  `// Generated by packages/ui/scripts/generate-tabler-filled-sprite.ts. Do not edit.`,
  `// Source: @tabler/icons ${tablerVersion} (MIT). See LICENSE-tabler-icons.txt.`,
  `import type { TablerFilledIconRecord } from "../types";`,
  ``,
  `export const TABLER_FILLED_CATEGORIES: readonly string[] = [`,
  ...categoryNames.map((name) => `  ${JSON.stringify(name)},`),
  `];`,
  ``,
  `export const TABLER_FILLED_ICONS: readonly TablerFilledIconRecord[] = [`,
  ...generatedIcons.map(
    ({ record }) =>
      `  { name: ${JSON.stringify(record.name)}, label: ${JSON.stringify(
        record.label
      )}, category: ${record.category}, tags: ${JSON.stringify(record.tags)} },`
  ),
  `];`,
  ``,
].join("\n");

await mkdir(outputDirectory, { recursive: true });

await mkdir(nameSetOutputDirectory, { recursive: true });

await writeFile(join(outputDirectory, "tabler-filled-sprite.svg"), sprite);

await writeFile(
  join(nameSetOutputDirectory, "tabler-filled-names.ts"),
  iconNames
);

await writeFile(join(outputDirectory, "tabler-filled-icons.ts"), metadata);

await writeFile(
  join(outputDirectory, "tabler-filled-symbol-prefix.ts"),
  symbolPrefix
);

await writeFile(
  join(outputDirectory, "LICENSE-tabler-icons.txt"),
  await readFile(join(tablerRoot, "LICENSE"), "utf8")
);

console.log(
  `Generated ${generatedIcons.length} icons in ${categoryNames.length} categories: ` +
    `sprite ${kilobytes(sprite)}, metadata ${kilobytes(metadata)}, ` +
    `names ${kilobytes(iconNames)}.`
);

async function generateIcon(
  icon: TablerIcon,
  category: number
): Promise<GeneratedIcon> {
  const source = await readFile(
    join(tablerRoot, "icons", "filled", `${icon.name}.svg`),
    "utf8"
  );

  const withoutBackground = source.replace(BACKGROUND_PATH_PATTERN, "");

  const optimized = optimize(withoutBackground, {
    multipass: true,
    // Two decimals is 0.01 of a 24-unit viewBox, which is sub-pixel at every
    // size the picker renders. SVGO's default of three costs most of the
    // sprite's path data for no visible difference.
    plugins: [{ name: "preset-default", params: { floatPrecision: 2 } }],
  }).data;

  const inner = optimized
    .replace(SVG_OPEN_PATTERN, "")
    .replace(SVG_CLOSE_PATTERN, "")
    .trim();

  if (inner === optimized) {
    throw new Error(`Could not extract the body of ${icon.name}.svg`);
  }

  return {
    record: {
      category,
      label: humanize(icon.name),
      name: icon.name,
      tags: searchableTags(icon),
    },
    symbol: `<symbol id="${SYMBOL_ID_PREFIX}${icon.name}" viewBox="0 0 24 24">${inner}</symbol>`,
  };
}

/**
 * `arrow-big-left` becomes `Arrow Big Left`, which is what the list announces.
 * The words stay in their original order so the label is still a true name.
 */
function humanize(name: string): string {
  return name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(" ");
}

/**
 * The tags `@tabler/icons` already curates, minus the ones the label already
 * contains: the search scores a label hit higher, so repeating a word in both
 * places only inflates the payload.
 */
function searchableTags(icon: TablerIcon): string[] {
  const labelWords = new Set(icon.name.split("-"));

  return [
    ...new Set(
      icon.tags
        .map((tag) => String(tag).toLowerCase().trim())
        .filter((tag) => tag.length > 0 && !labelWords.has(tag))
    ),
  ];
}

function compareNames(a: string, b: string): number {
  if (a < b) {
    return -1;
  }

  return a > b ? 1 : 0;
}

function kilobytes(value: string): string {
  return `${(Buffer.byteLength(value) / 1024).toFixed(1)} KB`;
}
